def solution(n, balances, links):
    parent = list(range(n + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # 경로 압축(절반)
            x = parent[x]
        return x

    for a, b in links:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    total = {}
    for i in range(1, n + 1):
        r = find(i)
        total[r] = total.get(r, 0) + balances[i - 1]
    return sorted(total.values(), reverse=True)
